#!/usr/bin/env python3
"""Writes bulk.c: N generated ARM functions that scale the synthetic firmware
up to the size of a real image (about 160 bytes a function at -O2), for
measuring imports (docs/api.md, "Import progress") and exercising the UI's
import progress. Deterministic: the same N gives the same file.

    bulk.py N > bulk.c

Function i calls 2i+1 and 2i+2 (a call tree from bulk_0, which main
reaches through bulk_root), every 7th switches through a jump table, every
11th is reached only through a table of code pointers, and every 13th is
called by nothing: only the start patterns find those, as in a real image.
"""
import sys

n = int(sys.argv[1])
out = ["/* Generated by bulk.py %d: do not edit. */" % n,
       "#define NOINLINE __attribute__((noinline))",
       "extern volatile int sink;",
       "typedef int (*bulk_fn)(int, int);"]
for i in range(n):
    out.append("NOINLINE int bulk_%d(int a, int b);" % i)
out.append("extern const bulk_fn bulk_table[8];")


def body(i):
    lines = ["  int r = a * %d + (b ^ %d);" % (i % 97 + 3, i * 2654435761 % 4093)]
    if i % 7 == 0:
        lines.append("  switch ((a + %d) & 7) {" % i)
        for c in range(7):
            lines.append("    case %d: r += b * %d - %d; break;" % (c, c + i % 5 + 2, c * 3 + i % 11))
        lines.append("    default: r ^= %d;" % (i % 251))
        lines.append("  }")
    if i % 3 == 0:
        lines.append("  for (int k = 0; k < (b & %d); k++) r = (r << 1) ^ (k + %d);" % (i % 15 + 1, i % 127))
    if i % 5 == 0:
        lines.append("  if (r & %d) sink = r; else sink = r + %d;" % (1 << (i % 9), i))
    for child in (2 * i + 1, 2 * i + 2):
        if child < n and child % 11 and child % 13:
            lines.append("  if (r & %d) r += bulk_%d(r, a);" % (1 << (child % 5), child))
    if i % 11 == 1:
        lines.append("  r += bulk_table[(a + r) & %d](b, r);" % 7)
    lines.append("  sink = r;")
    lines.append("  return r - %d;" % (i % 31))
    return lines


tabled = [i for i in range(n) if i % 11 == 0 and i % 13][:8] or [0]
while len(tabled) < 8:
    tabled.append(tabled[-1])
out.append("const bulk_fn bulk_table[8] = {%s};" % ", ".join("bulk_%d" % i for i in tabled))
for i in range(n):
    out.append("NOINLINE int bulk_%d(int a, int b) {" % i)
    out.extend(body(i))
    out.append("}")
out.append("int bulk_root(int a, int b) { return bulk_0(a, b) + bulk_table[a & 7](b, a); }")
sys.stdout.write("\n".join(out) + "\n")
